// --- Extension surface: `loadExtensionFromFactory` (loader.ts:464) takes an
// --- inline factory, so a closure captures the disposers. No temp file needed.
const extension = await loadExtensionFromFactory(
	async (api) => {
		disposeA = api.on("session_start", handlerA);
		disposeB = api.on("session_start", handlerB);
		disposeC = api.on("session_start", handlerC);
	},
	cwd,
	new EventBus(),
	new ExtensionRuntime(),
	"w1-probe",
);
expect(extension.handlers.get("session_start")).toHaveLength(3);

disposeA();
expect(extension.handlers.get("session_start")).toHaveLength(2);

// disposing the middle handler, then disposing it AGAIN, must not evict C
// (which has shifted into B's old slot)
disposeB();
expect(extension.handlers.get("session_start")).toEqual([handlerA, handlerC]);
disposeB(); // second call: no-op
expect(extension.handlers.get("session_start")).toEqual([handlerA, handlerC]);

disposeA();
disposeC();
expect(extension.handlers.has("session_start")).toBe(false); // key DELETED

